() => {
  const labels = Array.from(document.querySelectorAll('svg.SVGSpiral2026 a[id^="Spiral26Text-"]')).map(a => {
    const tspans = a.querySelectorAll('text tspan');
    const text = tspans.length ? Array.from(tspans).map(t => t.textContent.trim()).join(' ') : (a.querySelector('text')?.textContent || '').trim();
    return { id: a.id, text, ariaLabel: a.getAttribute('aria-label') };
  });
  return { lang: document.documentElement.lang, htmlLangFromBody: document.body.className.match(/lang-\S+/), count: labels.length, labels };
}

