    if ( ! $is_en ) return $pt;
    $en = isset( $row['segment_label_en'] ) ? trim( (string) $row['segment_label_en'] ) : '';
    if ( $en !== '' ) return $en;
    $fallback_en = $default_en_by_position[ $n ] ?? '';
    return $fallback_en !== '' ? $fallback_en : $pt;
};

