2858	### Snippet — Gate 37 (cross-blog srcset 4xx)
2859	
2860	Roda em PROD (sem header X-Test-Green) ou GREEN (com header). Varre 5+ páginas
2861	do blog 2 e detecta refs `/sites/N/uploads/` + 4xx em assets.
2862	
2863	```javascript
2864	// Snippet smoke (browser_run_code) — gate 37
2865	async (page) => {
2866	  const ctx = page.context();
2867	  await ctx.setExtraHTTPHeaders(HEADER_VAL || {});
2868	  await ctx.clearCookies();
2869	
2870	  const BASE = 'https://concertacaoamazonia.com.br';
2871	  const TARGET_BLOG = 2; // /cultura/
2872	  const PAGES = [
2873	    '/cultura/',
2874	    '/cultura/atlas-cultural-das-amazonias/',
2875	    '/cultura/poeticas-do-possivel/',
2876	    '/cultura/exposicao-cores-do-futuro/',
2877	    '/cultura/porosidades/',
2878	    '/cultura/galeria/',
2879	  ];
2880	
2881	  const results = [];
2882	
2883	  for (const path of PAGES) {
2884	    const failed4xx = [];
2885	    const responseHandler = (resp) => {
2886	      const u = resp.url();
2887	      const s = resp.status();
2888	      if (s >= 400 && s < 500 && /\/sites\/\d+\/uploads\//.test(u)) {
2889	        failed4xx.push({ status: s, url: u.slice(-100) });
2890	      }
2891	    };
2892	    page.on('response', responseHandler);
2893	
2894	    try {
2895	      await page.goto(`${BASE}${path}?cb=${Date.now()}`, { waitUntil: 'networkidle', timeout: 45000 });
2896	      // Lazy-load: scroll para forçar carregamento de imgs fora do viewport
2897	      await page.evaluate(async () => {
2898	        await new Promise(resolve => {
2899	          const total = document.body.scrollHeight;
2900	          let scrolled = 0;
2901	          const step = 500;
2902	          const timer = setInterval(() => {
2903	            window.scrollBy(0, step);
2904	            scrolled += step;
2905	            if (scrolled >= total) { clearInterval(timer); window.scrollTo(0, 0); resolve(); }
2906	          }, 100);
2907	        });
2908	      });
2909	      await page.waitForTimeout(1500);
2910	
2911	      const data = await page.evaluate((blog) => {
2912	        const re = new RegExp(`/sites/${blog}/uploads/`, 'g');
2913	        const html = document.documentElement.outerHTML;
2914	        const sites_n_in_html = (html.match(re) || []).length;
2915	        const imgs = Array.from(document.querySelectorAll('img'));
2916	        const broken = imgs.filter(i => i.complete && i.naturalWidth === 0 && i.src);
2917	        const srcset_with_sites_n = imgs.filter(i => re.test(i.srcset || '')).length;
2918	        const src_with_sites_n = imgs.filter(i => re.test(i.src || '')).length;
2919	        return {
2920	          total_imgs: imgs.length,
2921	          broken_count: broken.length,
2922	          broken_samples: broken.slice(0, 3).map(i => (i.currentSrc || i.src).split('/').slice(-2).join('/')),
2923	          srcset_with_sites_n,
2924	          src_with_sites_n,
2925	          sites_n_in_html_refs: sites_n_in_html,
2926	        };
2927	      }, TARGET_BLOG);
2928	
2929	      results.push({
2930	        path,
2931	        ...data,
2932	        failed_4xx_count: failed4xx.length,
2933	        failed_4xx_samples: failed4xx.slice(0, 3),
2934	      });
2935	    } catch (e) {
2936	      results.push({ path, error: (e.message || '?').slice(0, 120) });
